        assertDeepCopy(head, copy);
        assertEquals("[[1,1],[2,1]]", serialize(copy));
    }

    @Test
    @Disabled("Solution.java is intentionally incomplete")
    void shouldCopyListWithNullRandoms() {

        Solution solution = new Solution();
        Node head = buildList(new Integer[][]{
            {3, null}, {3, 0}, {3, null}
        });

        Node copy = solution.copyRandomList(head);

        assertDeepCopy(head, copy);
        assertEquals("[[3,null],[3,0],[3,null]]", serialize(copy));
    }

    @Test
    @Disabled("Solution.java is intentionally incomplete")
    void shouldReturnNullForEmptyList() {

        Solution solution = new Solution();

        assertNull(solution.copyRandomList(null));
    }

    @Test
    @Disabled("Solution.java is intentionally incomplete")
    void shouldCopySingleNodeWithoutRandom() {

        Solution solution = new Solution();
        Node head = buildList(new Integer[][]{{5, null}});

        Node copy = solution.copyRandomList(head);

        assertDeepCopy(head, copy);
        assertEquals("[[5,null]]", serialize(copy));
    }

    private Node buildList(Integer[][] nodes) {

        if (nodes.length == 0) {
            return null;
        }

        Node[] created = new Node[nodes.length];

        for (int i = 0; i < nodes.length; i++) {
            created[i] = new Node(nodes[i][0]);
        }

        for (int i = 0; i < nodes.length; i++) {
            if (i + 1 < nodes.length) {
                created[i].next = created[i + 1];
            }

            Integer randomIndex = nodes[i][1];
            if (randomIndex != null) {
                created[i].random = created[randomIndex];
            }
        }

        return created[0];
    }

    private void assertDeepCopy(Node original, Node copy) {

        Map<Node, Node> originalToCopy = new HashMap<>();
        Node a = original;
        Node b = copy;

        while (a != null) {
            assertNotNull(b);
            assertNotSame(a, b);
            assertEquals(a.val, b.val);
            originalToCopy.put(a, b);
            a = a.next;
            b = b.next;
        }

        assertNull(b);

        a = original;
        b = copy;

        while (a != null) {
            if (a.random == null) {
                assertNull(b.random);
            } else {
                assertNotNull(b.random);
                assertTrue(originalToCopy.get(a.random) == b.random);
            }
            a = a.next;
            b = b.next;
        }
    }

    private String serialize(Node head) {

        List<Node> nodes = new ArrayList<>();
        Map<Node, Integer> indexByNode = new HashMap<>();

        Node current = head;
        int index = 0;

        while (current != null) {
            nodes.add(current);
            indexByNode.put(current, index);
            current = current.next;
            index++;
        }

        StringBuilder sb = new StringBuilder();
        sb.append('[');

        for (int i = 0; i < nodes.size(); i++) {
            if (i > 0) {
                sb.append(',');
            }

            Node node = nodes.get(i);
            sb.append('[').append(node.val).append(',');

            if (node.random == null) {
                sb.append("null");
            } else {
                sb.append(indexByNode.get(node.random));
            }

            sb.append(']');
        }

        sb.append(']');
        return sb.toString();
    }
}

